mapper.select:
/* 커뮤니티 (공지사항) 조회 쿼리 (selectNotice)*/ select NOTICE_SEQNO as noticeSeqno ,NOTICE_TTL as noticeTtl ,NOTICE_CN as noticeCn ,VIEW_CNT as viewCnt ,USE_YN as useYn ,NOTICE_MSG_DVCD as noticeMsgDvcd ,NOTICE_TYPE_CD as noticeTypeCd ,FAQ_ANSMER as faqAnsmer ,to_char(TO_DATE(STDD,'YYYYMMDD'),'YYYY-MM-DD') as stdd ,to_char(TO_DATE(ENDT,'YYYYMMDD'),'YYYY-MM-DD') as endt ,ATCH_FILE_ID as atchFileId ,LAST_CHNG_EMPNO as lastChngEmpno from ocuoc_notic_m where 1=1
and NOTICE_TYPE_CD = #{noticeTypeCd}
and NOTICE_TTL like '%'||#{noticeTtl}||'%'
and STDD >= replace(#{startDate},'-','')
and ENDT > replace(#{endDate},'-','')
ORDER BY NOTICE_SEQNO DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

/* 커뮤니티 (공지사항) 페이징 총카운터 조회 쿼리 (selectNoticeCount)*/ select count(*) from ocuoc_notic_m where 1=1
and NOTICE_TYPE_CD = #{noticeTypeCd}
and NOTICE_TTL like '%'||#{noticeTtl}||'%'
and STDD >= replace(#{startDate},'-','')
and ENDT > replace(#{endDate},'-','')

mapper.insert:
/* 커뮤니티 (공지사항) 저장 쿼리 (insertNotice)*/
INSERT INTO ocuoc_notic_m
( NOTICE_SEQNO
, NOTICE_TYPE_CD
, NOTICE_TTL
, NOTICE_CN
, VIEW_CNT
, USE_YN
, NOTICE_MSG_DVCD
, STDD
, ENDT
, ATCH_FILE_ID
, FAQ_ANSMER
, LAST_CHNG_EMPNO
, LAST_CHNG_DTTM
, FRST_REG_EMPNO
, FRST_REG_DTTM)
VALUES ( (select NVL(max(NOTICE_SEQNO), 0) + 1
          from ocuoc_notic_m
          where NOTICE_TYPE_CD = #{noticeTypeCd})
       , #{noticeTypeCd}
       , #{noticeTtl}
       , #{noticeCn}
       , #{viewCnt}
       , #{useYn}
       , #{noticeMsgDvcd}
       , replace(#{stdd},'-','')
       , replace(#{endt},'-','')
       , #{atchFileId}
       , #{faqAnsmer}
       , #{lastChngEmpno}
       , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
       , #{lastChngEmpno}
       , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
       )

/* 커뮤니티 (공지사항) 첨부파일 저장 쿼리 (insertAttachFile)*/
INSERT INTO couoc_atchf_m
( ATCH_FILE_ID
, FILE_SEQ
, ORG_FILE_NM
, SAVE_FILE_NM
, FILE_PATH
, FILE_SIZE
, FILE_EXT
, REG_DT)
VALUES (
         #{atchFileId}
       , #{fileSeq}
       , #{orgFileNm}
       , #{saveFileNm}
       , #{filePath}
       , #{fileSize}
       , #{fileExt}
       , to_char(sysdate,'yyyymmdd')
       )

mapper.update:
/* 커뮤니티 (공지사항) 상세 수정 쿼리 (updateDetailNotice)*/
update ocuoc_notic_m
set NOTICE_TTL       = #{noticeTtl}
  , NOTICE_CN        = #{noticeCn}
  , STDD             = replace(#{stdd},'-','')
  , ENDT             = replace(#{endt},'-','')
  , FAQ_ANSMER       = #{faqAnsmer}
  , ATCH_FILE_ID     = #{atchFileId}
  , LAST_CHNG_EMPNO  = #{lastChngEmpno}
  , LAST_CHNG_DTTM   = TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
WHERE NOTICE_SEQNO   = #{noticeSeqno}
  and NOTICE_TYPE_CD = #{noticeTypeCd}

mapper.delete:
/* 커뮤니티 (공지사항) 삭제 쿼리 (deleteNoticeSeq)*/
DELETE
FROM ocuoc_notic_m
WHERE NOTICE_SEQNO = #{noticeSeqno}
AND   NOTICE_TYPE_CD = #{noticeTypeCd}

/* 커뮤니티 (공지사항) 첨부파일 삭제 쿼리 (deleteAttachFileList)*/
DELETE
FROM ocuoc_atchf_m
WHERE ATCH_FILE_ID = #{atchFileId}

mapper.update:
/* 커뮤니티 (공지사항) 조회수증가 쿼리 (updateNoticeViewCnt)*/
update ocuoc_notic_m
set VIEW_CNT =  NVL(TO_NUMBER(VIEW_CNT),0)+1
WHERE NOTICE_SEQNO = #{noticeSeqno}
 and NOTICE_TYPE_CD = #{noticeTypeCd}
